<?php
declare(strict_types=1);namespace Liberu\Accounting\FixedAssetsApi\Http\Controllers;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Routing\Controller;use Liberu\Accounting\FixedAssets\Actions\{AcquireAsset,AddAssetDocument,CapitalizeAsset,CreateCategory};use Liberu\Accounting\FixedAssets\Enums\AssetStatus;use Liberu\Accounting\FixedAssets\Models\{Asset,AssetCategory};use Liberu\Accounting\FixedAssets\Queries\AssetQuery;use Liberu\Accounting\FixedAssetsApi\Http\Resources\AssetResource;final class FixedAssetsController extends Controller {public function __construct(private readonly AssetQuery $query){}public function index(Request $r):AssetResource{$s=$r->filled('status')?AssetStatus::from($r->string('status')->toString()):null;return new AssetResource($this->query->paginate($r->integer('team_id')?:null,$s,$r->integer('per_page',25)));}public function category(Request $r,CreateCategory $a):JsonResponse{return response()->json(['data'=>$a->handle($r->validate(['team_id'=>'nullable|integer','category_ref'=>'required|string|max:100','name'=>'required|string|max:255','asset_account_ref'=>'required|string|max:255','depreciation_account_ref'=>'required|string|max:255','useful_life_months'=>'required|integer|min:1','depreciation_method'=>'required|string|max:100'])],201);}public function store(Request $r,AssetCategory $category,AcquireAsset $a):AssetResource{return new AssetResource($a->handle($category,$r->all()));}public function show(Asset $asset):AssetResource{return new AssetResource($asset->load(['category','components','books','documents']));}public function capitalize(Request $r,Asset $asset,CapitalizeAsset $a):AssetResource{return new AssetResource($a->handle($asset,$r->validate(['book_ref'=>'required|string|max:100'])['book_ref']));}public function document(Request $r,Asset $asset,AddAssetDocument $a):AssetResource{$d=$r->validate(['document_ref'=>'required|string|max:100','kind'=>'required|string|max:100','file_ref'=>'required|string|max:500','description'=>'nullable|string|max:5000','checksum'=>'nullable|string|max:255','attached_by'=>'required|string|max:255','metadata'=>'nullable|array']);$a->handle($asset,$d);return new AssetResource($asset->load('documents'));}public function summary(Asset $asset,AssetQuery $q):JsonResponse{return response()->json(['data'=>$q->registerSummary($asset->load(['books','documents']) )]);}}
